      params = params.set('from', filter.from);
    }
    if (filter?.to) {
      params = params.set('to', filter.to);
    }
    if (filter?.venueId) {
      params = params.set('venueId', filter.venueId);
    }
    return this.http.get<EventListItem[]>('/api/events', { params });
  }
}

